import React from "react";
import { AbsoluteFill, Img, interpolate, staticFile, useCurrentFrame } from "remotion";
import { Back, Cam, Charger, Col, FPS, GRAD, GREEN, GREEN_D, INK, INTER, Icon, LINE, MINT, MUTED, Phone, Pill, WHITE, Words, cl, io, k, lin, mix, sp } from "./parts";

// e-posto Pay (cliente Aladim Bueno) — anúncio motion de 46 s, 1 foto (o logo) → jeito "motion".
// Referências: Micael Ananias (celular e cartões de interface contando a história) e NEAFH (limpo, claro, checklist).
// Locução o locutor (ElevenLabs v3) com as pausas longas encurtadas: public/aladim/voz-v1-edit.wav, entra em 0,15 s.
// Tempos escritos no tempo da locução (transcrição palavra a palavra); v() soma o atraso. Sem áudio aqui (mix à parte).

export const AL_FPS = FPS;
export const AL_FRAMES = 46 * FPS;
const VO = 0.15;
const v = (s: number) => s + VO;
const asset = (f: string) => staticFile(`aladim/${f}`);

// trocas de cena (tempo da locução)
const T2 = 3.55; // inundação verde: "Chegou o e-posto Pay"
const T3 = 8.6; // cortina sobe: "Esqueça..."
const T4 = 15.18; // cortina lateral: "Aqui, a experiência é direta"
const T5 = 18.0; // a linha vira o passo a passo, o celular sobe
const T8 = 29.15; // círculo menta sai do celular: "simples assim"
const T9 = 35.0; // inundação verde sai da última pílula: "Conheça"
const T10 = 39.82; // cortina desce: contato

const flood = (t: number, at: number, x: number, y: number, d = 0.55) => {
  const r = interpolate(t, [v(at), v(at) + d], [0, 2300], { ...cl, easing: (u) => u * u * (3 - 2 * u) });
  return `circle(${r.toFixed(1)}px at ${x}px ${y}px)`;
};
const wipe = (t: number, at: number, dir: "up" | "left" | "down", d = 0.5) => {
  const p = 1 - io(t, v(at), d);
  const q = (p * 100).toFixed(2);
  if (dir === "up") return `inset(${q}% 0 0 0 round 90px 90px 0 0)`;
  if (dir === "down") return `inset(0 0 ${q}% 0 round 0 0 90px 90px)`;
  return `inset(0 0 0 ${q}% round 90px 0 0 90px)`;
};

// ───────── 1 · "Cansado de baixar um aplicativo para cada recarga?" ─────────
const APP_COLORS = ["#6C7A89", "#E67E22", "#8E44AD", "#16A085", "#C0392B", "#2C3E50", "#D35400", "#2980B9", "#7F8C8D"];
const Cena1: React.FC<{ t: number }> = ({ t }) => (
  <Cam t={t} a={0} b={v(T2) + 0.4} s0={1.07} s1={1} y0={30}>
    <Back />
    <Col top={280}>
      <Words t={t} size={96} words={[["Cansado", v(0.02)], ["de", v(0.42)]]} />
      <Words t={t} size={96} words={[["baixar", v(0.88)], ["um", v(1.24)]]} />
      <Words t={t} size={96} words={[["aplicativo", v(1.36)], ["para", v(1.98)]]} />
      <Words t={t} size={96} words={[["cada", v(2.21), GREEN], ["recarga?", v(2.44), GREEN]]} />
    </Col>
    <div style={{ position: "absolute", left: 200, top: 770, width: 680, display: "flex", flexWrap: "wrap", gap: 40 }}>
      {APP_COLORS.map((c, i) => {
        const at = v(0.15 + i * 0.29);
        const e = sp(t, at, 170);
        const fill = interpolate(t, [at + 0.2, at + 1.6], [0, 1], cl);
        return (
          <div key={i} style={{ width: 200, height: 260, display: "flex", flexDirection: "column", alignItems: "center", gap: 18, opacity: Math.min(1, e * 2), transform: `scale(${(0.4 + 0.6 * e).toFixed(3)})` }}>
            <div style={{ position: "relative", width: 200, height: 200, borderRadius: 52, background: c, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 16px 30px rgba(0,0,0,0.14)" }}>
              <Icon name={i % 2 ? "zap" : "plug"} size={92} color="#fff" stroke={2.2} />
              <div style={{ position: "absolute", right: -14, top: -14, width: 70, height: 70, borderRadius: 40, background: WHITE, border: `3px solid ${LINE}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <Icon name="download" size={38} color={INK} stroke={2.6} />
              </div>
            </div>
            <div style={{ width: 170, height: 16, borderRadius: 10, background: "#DCE7E0", overflow: "hidden" }}>
              <div style={{ width: `${(fill * 100).toFixed(1)}%`, height: "100%", borderRadius: 10, background: GRAD }} />
            </div>
          </div>
        );
      })}
    </div>
  </Cam>
);

// ───────── 2 · "Chegou o e-posto Pay: sem cadastro e sem aplicativo!" ─────────
const Cena2: React.FC<{ t: number }> = ({ t }) => {
  const card = sp(t, v(3.62), 150);
  const logo = sp(t, v(3.95), 160);
  return (
    <Cam t={t} a={v(T2)} b={v(T3) + 0.5} s0={1.1} s1={1.0} y0={-40}>
      <Back green />
      <Col top={370}>
        <Words t={t} size={72} color={WHITE} words={[["Chegou", v(3.7)], ["o", v(3.9)]]} />
      </Col>
      <div style={{ position: "absolute", left: 160, top: 490, width: 760, height: 590, borderRadius: 64, background: WHITE, boxShadow: "0 40px 80px rgba(0,50,20,0.28)", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(0.5 + 0.5 * card).toFixed(3)})`, opacity: Math.min(1, card * 2.5) }}>
        <Img src={asset("logo.png")} style={{ width: 520, transform: `scale(${(0.7 + 0.3 * logo).toFixed(3)})`, opacity: Math.min(1, logo * 2) }} />
      </div>
      {[["user", "Sem cadastro", 5.66, 1170], ["phone", "Sem aplicativo", 6.74, 1345]].map(([ic, tx, at, top]) => {
        const e = sp(t, v(at as number), 150);
        return (
          <div key={tx as string} style={{ position: "absolute", left: 160, top: top as number, opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 120).toFixed(1)}px)` }}>
            <Pill icon={ic as string} text={tx as string} w={760} h={145} dark slash={k(t, v(at as number) + 0.25, 0.35)} />
          </div>
        );
      })}
    </Cam>
  );
};

// ───────── 3 · "Esqueça a perda de tempo criando contas e preenchendo formulários..." ─────────
const FIELDS: [string, number, boolean?][] = [["Nome completo", 9.6], ["E-mail", 10.3], ["CPF", 11.0], ["Senha", 11.7, true], ["Confirmar senha", 12.4, true]];
const Cena3: React.FC<{ t: number }> = ({ t }) => {
  const cardIn = sp(t, v(8.7), 140);
  const strike = k(t, v(14.05), 0.4);
  const fade = k(t, v(14.0), 0.6);
  return (
    <Cam t={t} a={v(T3)} b={v(T4) + 0.5} s0={1.0} s1={1.02}>
      <Back />
      <Col top={285}>
        <Words t={t} size={100} words={[["Esqueça", v(8.76)], ["a", v(8.9)]]} />
        <Words t={t} size={100} words={[["perda", v(8.98)], ["de", v(9.15)], ["tempo", v(9.25), GREEN]]} />
      </Col>
      <div style={{ position: "absolute", left: 140, top: 540, width: 800, transform: `translateY(${((1 - cardIn) * 260).toFixed(1)}px) scale(${mix(1, 0.94, fade).toFixed(3)})`, opacity: Math.min(1, cardIn * 2) }}>
        <div style={{ background: WHITE, borderRadius: 52, border: `3px solid ${LINE}`, boxShadow: "0 30px 70px rgba(16,60,30,0.12)", padding: "38px 50px 44px", filter: `grayscale(${fade.toFixed(2)})`, opacity: mix(1, 0.55, fade) }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
            <div style={{ fontFamily: INTER, fontWeight: 800, fontSize: 50, letterSpacing: "-0.03em", color: INK }}>Criar conta</div>
            <svg width={64} height={64} viewBox="0 0 24 24" fill="none" stroke={MUTED} strokeWidth={2} strokeLinecap="round">
              <circle cx="12" cy="12" r="10" />
              <path d="M12 12V6" transform={`rotate(${(t * 140).toFixed(1)} 12 12)`} />
              <path d="M12 12h3.5" transform={`rotate(${(t * 12).toFixed(1)} 12 12)`} />
            </svg>
          </div>
          {FIELDS.map(([label, at, secret], i) => {
            const p = lin(t, v(at), v(at) + 0.6);
            const on = t >= v(at) && t < v(at) + 0.7;
            return (
              <div key={i} style={{ marginBottom: 12 }}>
                <div style={{ fontFamily: INTER, fontWeight: 600, fontSize: 28, color: MUTED, marginBottom: 6 }}>{label}</div>
                <div style={{ height: 70, borderRadius: 20, border: `3px solid ${on ? GREEN : "#E3EAE5"}`, background: "#FAFCFB", display: "flex", alignItems: "center", padding: "0 26px", overflow: "hidden" }}>
                  {secret ? (
                    <div style={{ display: "flex", gap: 12 }}>{Array.from({ length: 10 }, (_, j) => <div key={j} style={{ width: 16, height: 16, borderRadius: 10, background: INK, opacity: j / 10 < p ? 0.75 : 0 }} />)}</div>
                  ) : (
                    <div style={{ width: `${(p * (i === 1 ? 82 : 66)).toFixed(1)}%`, height: 20, borderRadius: 12, background: "#C9D3CD" }} />
                  )}
                  {on ? <div style={{ width: 4, height: 40, marginLeft: 8, background: GREEN, opacity: Math.floor(t * 4) % 2 ? 1 : 0.2 }} /> : null}
                </div>
              </div>
            );
          })}
          <div style={{ marginTop: 12, height: 84, borderRadius: 50, background: "#DCE5DF", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: INTER, fontWeight: 800, fontSize: 36, color: "#8A978F" }}>Continuar</div>
        </div>
        <svg width={800} height={900} viewBox="0 0 800 900" style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
          <path d="M60 110 L740 820" stroke={INK} strokeWidth={18} strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - strike} />
        </svg>
      </div>
    </Cam>
  );
};

// ───────── 4 → 7 · "A experiência é direta": a linha vira o passo a passo ─────────
const STEPS = [18.48, 22.56, 24.56];
const Stepper: React.FC<{ t: number }> = ({ t }) => {
  const draw = k(t, v(16.8), 0.7);
  const up = io(t, v(T5), 0.55);
  const y = mix(1190, 312, up);
  const sc = mix(1, 0.78, up);
  const prog = interpolate(t, [v(STEPS[0]), v(STEPS[1]), v(STEPS[2])], [0, 0.5, 1], { ...cl, easing: (u) => u });
  const fillTo = (i: number) => interpolate(t, [v(STEPS[i]) - 0.05, v(STEPS[i]) + 0.35], [0, 1], cl);
  return (
    <div style={{ position: "absolute", left: 160, top: y - 48, width: 760, height: 96, transform: `scale(${sc.toFixed(3)})` }}>
      <div style={{ position: "absolute", left: 48, top: 42, width: 664 * draw, height: 12, borderRadius: 8, background: LINE }} />
      <div style={{ position: "absolute", left: 48, top: 42, width: 664 * Math.max(prog > 0 ? prog : 0, 0), height: 12, borderRadius: 8, background: GRAD }} />
      {[0, 1, 2].map((i) => {
        const e = sp(t, v(17.25 + i * 0.16), 170);
        const f = fillTo(i);
        return (
          <div key={i} style={{ position: "absolute", left: i * 332, top: 0, width: 96, height: 96, borderRadius: 60, background: f > 0.5 ? GREEN : WHITE, border: `5px solid ${f > 0.02 ? GREEN : LINE}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(e * (1 + 0.12 * Math.sin(Math.PI * f))).toFixed(3)})`, fontFamily: INTER, fontWeight: 800, fontSize: 44, color: f > 0.5 ? WHITE : INK }}>{i + 1}</div>
        );
      })}
    </div>
  );
};
const Cena4: React.FC<{ t: number }> = ({ t }) => {
  const out = 1 - k(t, v(T5) - 0.1, 0.18);
  return (
    <AbsoluteFill style={{ opacity: out }}>
      <Col top={690}>
        <Words t={t} size={104} words={[["Aqui,", v(15.3)], ["a", v(15.45)]]} />
        <Words t={t} size={104} words={[["experiência", v(15.5)]]} />
        <Words t={t} size={104} words={[["é", v(16.7)], ["direta.", v(16.8), GREEN]]} />
      </Col>
    </AbsoluteFill>
  );
};
// rótulo de cada passo: fica parado; o anterior some inteiro antes do próximo entrar
const StepLabel: React.FC<{ t: number }> = ({ t }) => {
  const shown = (a: number, b: number) => t >= v(a) - 0.05 && t < v(b) - 0.12;
  const op = (b: number) => 1 - lin(t, v(b) - 0.3, v(b) - 0.14);
  return (
    <Col top={405} style={{ height: 200 }}>
      {shown(18.48, 22.56) ? (
        <div style={{ opacity: op(22.56) }}>
          <Words t={t} size={70} words={[["Aponte", v(18.55)], ["a", v(18.95)], ["câmera", v(19.02)]]} />
          <Words t={t} size={70} words={[["e", v(19.68)], ["leia", v(19.7)], ["o", v(20.08)], ["QR", v(20.15), GREEN], ["Code", v(20.33), GREEN]]} />
        </div>
      ) : null}
      {shown(22.56, 24.56) ? (
        <div style={{ opacity: op(24.56), paddingTop: 40 }}>
          <Words t={t} size={70} words={[["Realize", v(22.74)], ["o", v(23.35)], ["pagamento", v(23.45), GREEN]]} />
        </div>
      ) : null}
      {shown(24.56, 40) ? (
        <div>
          <Words t={t} size={70} words={[["Pronto!", v(25.12), GREEN], ["A", v(25.94)], ["recarga", v(26.04)]]} />
          <Words t={t} size={70} words={[["começa", v(26.94)], ["na", v(27.53)], ["hora", v(27.73), GREEN]]} />
        </div>
      ) : null}
    </Col>
  );
};

// telas do celular
const SW = 489;
const SH = 1019;
const TelaCamera: React.FC<{ t: number }> = ({ t }) => {
  const zoom = io(t, v(19.0), 1.2);
  const read = t >= v(20.4);
  const ok = sp(t, v(20.45), 170);
  const scan = (Math.sin((t - v(18.5)) * 4.2) + 1) / 2;
  const bc = read ? GREEN : WHITE;
  const B = ({ x, y, r }: { x: number; y: number; r: number }) => (
    <div style={{ position: "absolute", left: x, top: y, width: 50, height: 50, borderLeft: `8px solid ${bc}`, borderTop: `8px solid ${bc}`, borderTopLeftRadius: 18, transform: `rotate(${r}deg)` }} />
  );
  return (
    <div style={{ position: "absolute", inset: 0, background: "#26343D", overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, transform: `scale(${mix(1, 1.42, zoom).toFixed(3)})`, transformOrigin: "244px 375px" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 640, bottom: 0, background: "#1D2930" }} />
        <div style={{ position: "absolute", left: 124, top: 200 }}><Charger w={240} cable={1} /></div>
      </div>
      <div style={{ position: "absolute", left: 104, top: 210, width: 280, height: 300, transform: `scale(${(1 + 0.06 * Math.sin(Math.PI * Math.min(1, ok))).toFixed(3)})` }}>
        <B x={0} y={0} r={0} />
        <B x={230} y={0} r={90} />
        <B x={230} y={250} r={180} />
        <B x={0} y={250} r={270} />
        {!read ? <div style={{ position: "absolute", left: 20, right: 20, top: 20 + scan * 250, height: 6, borderRadius: 4, background: GREEN, boxShadow: "0 0 14px rgba(76,199,42,0.8)" }} /> : null}
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 70, textAlign: "center", fontFamily: INTER, fontWeight: 700, fontSize: 30, color: "rgba(255,255,255,0.85)" }}>Câmera</div>
      <div style={{ position: "absolute", left: "50%", top: 676, width: 104, height: 104, marginLeft: -52, borderRadius: 60, border: "6px solid #fff", boxSizing: "border-box", opacity: 1 - ok }} />
      <div style={{ position: "absolute", left: 50, right: 50, top: 668, height: 120, borderRadius: 60, background: WHITE, display: "flex", alignItems: "center", justifyContent: "center", gap: 18, opacity: Math.min(1, ok * 2), transform: `translateY(${((1 - ok) * 80).toFixed(1)}px)` }}>
        <div style={{ width: 66, height: 66, borderRadius: 40, background: GRAD, display: "flex", alignItems: "center", justifyContent: "center" }}><Icon name="check" size={40} color="#fff" stroke={3} /></div>
        <div style={{ fontFamily: INTER, fontWeight: 800, fontSize: 38, color: INK, letterSpacing: "-0.02em" }}>QR Code lido</div>
      </div>
    </div>
  );
};
const TelaPagamento: React.FC<{ t: number }> = ({ t }) => {
  const sel = sp(t, v(23.0), 170);
  const fx = io(t, v(23.15), 0.42);
  const press = t >= v(23.6) && t < v(23.75) ? 0.93 : 1;
  const morph = k(t, v(23.75), 0.35);
  const done = sp(t, v(24.12), 170);
  const bw = mix(SW - 100, 120, morph);
  const Opt = ({ icon, txt, on, top }: { icon: string; txt: string; on: number; top: number }) => (
    <div style={{ position: "absolute", left: 40, right: 40, top, height: 130, borderRadius: 32, border: `4px solid ${on > 0.5 ? GREEN : "#E3EAE5"}`, background: on > 0.5 ? "#F0FAF3" : WHITE, display: "flex", alignItems: "center", gap: 22, padding: "0 30px", boxSizing: "border-box" }}>
      <Icon name={icon} size={52} color={GREEN} stroke={2.2} />
      <div style={{ flex: 1, fontFamily: INTER, fontWeight: 800, fontSize: 38, color: INK, letterSpacing: "-0.02em" }}>{txt}</div>
      <div style={{ width: 46, height: 46, borderRadius: 30, border: `4px solid ${on > 0.5 ? GREEN : "#C9D3CD"}`, display: "flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box" }}>
        <div style={{ width: 24 * on, height: 24 * on, borderRadius: 20, background: GREEN }} />
      </div>
    </div>
  );
  return (
    <div style={{ position: "absolute", inset: 0, background: WHITE }}>
      <div style={{ position: "absolute", left: 40, top: 96, fontFamily: INTER, fontWeight: 800, fontSize: 52, color: INK, letterSpacing: "-0.03em" }}>Pagamento</div>
      <div style={{ position: "absolute", left: 40, top: 164, fontFamily: INTER, fontWeight: 700, fontSize: 30, color: GREEN }}>e-posto Pay</div>
      <div style={{ position: "absolute", left: 40, right: 40, top: 226, height: 170, borderRadius: 32, background: MINT, border: `3px solid ${LINE}`, display: "flex", alignItems: "center", gap: 26, padding: "0 30px", boxSizing: "border-box" }}>
        <div style={{ width: 110, height: 110, borderRadius: 30, background: GRAD, display: "flex", alignItems: "center", justifyContent: "center" }}><Icon name="zap" size={60} color="#fff" stroke={2.2} /></div>
        <div style={{ fontFamily: INTER, fontWeight: 800, fontSize: 36, color: INK, lineHeight: 1.2 }}>Recarga do<br />seu veículo</div>
      </div>
      <Opt icon="pix" txt="Pix" on={sel} top={420} />
      <Opt icon="card" txt="Cartão" on={0} top={566} />
      <div style={{ position: "absolute", left: (SW - bw) / 2, top: 716, width: bw, height: 110, borderRadius: 70, background: GRAD, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${press})`, boxShadow: "0 16px 30px rgba(19,162,67,0.3)" }}>
        {morph < 0.3 ? <div style={{ fontFamily: INTER, fontWeight: 800, fontSize: 44, color: WHITE, opacity: 1 - morph * 3 }}>Pagar</div> : null}
        {morph >= 0.3 && done < 0.05 ? (
          <svg width={60} height={60} viewBox="0 0 24 24" style={{ transform: `rotate(${(t * 720).toFixed(0)}deg)` }}><path d="M12 3a9 9 0 0 1 9 9" fill="none" stroke="#fff" strokeWidth={3} strokeLinecap="round" /></svg>
        ) : null}
        {done >= 0.05 ? <Icon name="check" size={64} color="#fff" stroke={3.4} style={{ transform: `scale(${done.toFixed(3)})` }} /> : null}
      </div>
      {/* dedo: um toque no botão */}
      {(() => {
        const go = io(t, v(23.15), 0.42);
        const vis = interpolate(t, [v(23.05), v(23.2), v(23.85), v(24.0)], [0, 1, 1, 0], cl);
        const x = mix(400, SW / 2, go);
        const y = mix(900, 771, go);
        const s = t >= v(23.6) && t < v(23.75) ? 0.8 : 1;
        return <div style={{ position: "absolute", left: x - 45, top: y - 45, width: 90, height: 90, borderRadius: 50, background: "rgba(26,38,46,0.28)", border: "4px solid rgba(255,255,255,0.9)", opacity: vis * (fx > 0 ? 1 : 0), transform: `scale(${s})` }} />;
      })()}
    </div>
  );
};
const TelaRecarga: React.FC<{ t: number }> = ({ t }) => {
  const e = sp(t, v(24.7), 150);
  const fill = interpolate(t, [v(25.2), v(29.4)], [0.12, 0.92], cl);
  const ok = sp(t, v(25.12), 170);
  const msg = sp(t, v(26.0), 160);
  return (
    <div style={{ position: "absolute", inset: 0, background: GRAD }}>
      <div style={{ position: "absolute", left: "50%", top: 100, width: 112, height: 112, marginLeft: -56, borderRadius: 60, background: WHITE, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${ok.toFixed(3)})` }}>
        <Icon name="check" size={66} color={GREEN} stroke={3.2} />
      </div>
      <div style={{ position: "absolute", left: (SW - 230) / 2, top: 240, width: 230, height: 420, transform: `scale(${(0.6 + 0.4 * e).toFixed(3)})`, opacity: Math.min(1, e * 2) }}>
        <div style={{ position: "absolute", left: 75, top: 0, width: 80, height: 30, borderRadius: "14px 14px 0 0", background: WHITE }} />
        <div style={{ position: "absolute", left: 0, top: 26, width: 230, height: 394, borderRadius: 44, border: "12px solid #fff", boxSizing: "border-box", overflow: "hidden" }}>
          <div style={{ position: "absolute", left: 10, right: 10, bottom: 10, height: `${(fill * 352).toFixed(1)}px`, borderRadius: 26, background: "rgba(255,255,255,0.92)" }} />
          <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}><Icon name="zap" size={130} color={GREEN_D} stroke={2} /></div>
        </div>
