// verde em degradê (#4CC72A → #0E9A47), marinho #1A262E no texto, Inter pesada e apertada como no título do site,
// cartões brancos de canto bem arredondado com borda verde clara.

const { fontFamily } = loadInter("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });
