export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
// mola com pouco overshoot (3–5 %)
export const sp = (t: number, at: number, stiff = 140) => (t < at ? 0 : spring({ frame: (t - at) * FPS, fps: FPS, config: { damping: 17, stiffness: stiff, mass: 0.8 } }));
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;

