// ───────── QR Code genérico (determinístico) ─────────
const QR_N = 21;
const qrCell = (x: number, y: number) => {
  const inF = (fx: number, fy: number) => x >= fx && x < fx + 7 && y >= fy && y < fy + 7;
  for (const [fx, fy] of [[0, 0], [14, 0], [0, 14]]) {
    if (inF(fx, fy)) { const dx = x - fx, dy = y - fy; const ring = Math.min(dx, dy, 6 - dx, 6 - dy); return ring !== 1; }
  }
  if ((x === 7 || y === 7 || x === 13 || y === 13) && (x < 8 || y < 8 || (x > 12 && y < 8) || (y > 12 && x < 8))) return false;
  const h = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
  return h - Math.floor(h) > 0.52;
};
export const QR: React.FC<{ size: number; color?: string }> = ({ size, color = INK }) => {
  const c = size / QR_N;
  const rects: React.ReactNode[] = [];
  for (let y = 0; y < QR_N; y++) for (let x = 0; x < QR_N; x++) if (qrCell(x, y)) rects.push(<rect key={`${x}-${y}`} x={x * c} y={y * c} width={c + 0.4} height={c + 0.4} fill={color} />);
  return <svg width={size} height={size}>{rects}</svg>;
};

